-- BMLT NHPC: Clinical Microbiology – Diagnostic Methods & Specimen Processing
-- 25 MCQ Practice + 25 Mock Test questions
-- Import into Supabase SQL Editor and run.

begin;

on conflict (content_id) do nothing;

commit;

select content_type, count(*) as total_questions
from public.learning_content
where faculty = 'BMLT'
  and subject = 'BMLT NHPC Licensing'
  and content_data->>'topic' = 'Clinical Microbiology – Diagnostic Methods & Specimen Processing'
group by content_type
order by content_type;
