insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('bmlt-clinmicrodiagnostic1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Which specimen is preferred for routine bacterial culture of suspected urinary tract infection?","translation":"","options":["Fresh midstream clean-catch urine","First morning saliva","24-hour stool","Unpreserved sputum"],"correctIndex":0,"explanation":"A clean-catch midstream urine sample reduces contamination from urethral and perineal flora.","explanationNe":"UTI शंकामा सफा तरिकाले संकलन गरिएको midstream urine उपयुक्त हुन्छ; यसले बाहिरी जीवाणुको contamination घटाउँछ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Urine culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Which transport medium is commonly used for stool specimens when enteric pathogens are suspected and delay is expected?","translation":"","options":["Cary-Blair medium","Löwenstein-Jensen medium","Amies charcoal only","Thioglycollate broth"],"correctIndex":0,"explanation":"Cary-Blair is a buffered transport medium used for enteric bacterial pathogens in stool.","explanationNe":"दिसामा आन्द्राका रोगजनक जीवाणु जाँच्न ढिलाइ हुने अवस्थामा Cary-Blair transport medium प्रयोग गरिन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Transport media"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"What is the main purpose of collecting a sputum specimen early in the morning?","translation":"","options":["It is often more concentrated with respiratory secretions","It is always sterile","It contains no oral flora","It prevents bacterial growth"],"correctIndex":0,"explanation":"Overnight accumulation can make early-morning sputum more representative of lower respiratory secretions.","explanationNe":"रातभरि श्वासनलीमा जम्मा भएको secretion का कारण बिहानको खकार lower respiratory sample का रूपमा बढी उपयोगी हुन सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Respiratory specimens"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Which specimen is best for diagnosing bacterial meningitis?","translation":"","options":["Cerebrospinal fluid","Urine","Nasal swab","Skin scraping"],"correctIndex":0,"explanation":"CSF collected by lumbar puncture is the key specimen for suspected meningitis and must be processed urgently.","explanationNe":"Meningitis शंकामा lumbar puncture बाट लिइएको CSF मुख्य नमुना हो र तुरुन्त प्रयोगशालामा पठाउनुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"CSF processing"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Which action should be taken first when a specimen arrives without a patient identifier?","translation":"","options":["Reject or hold it according to laboratory policy and request recollection","Guess the patient''s identity","Process it and label later","Use the ward number as the patient name"],"correctIndex":0,"explanation":"An unlabelled or inadequately identified specimen creates a serious patient-safety risk.","explanationNe":"पहिचान नभएको नमुना गलत बिरामीसँग जोडिन सक्छ; प्रयोगशालाको नियमअनुसार रोक्ने वा अस्वीकार गरी पुनः नमुना माग्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen rejection"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Why should blood culture bottles be inoculated at the bedside when possible?","translation":"","options":["To reduce contamination and preserve correct blood-to-broth ratio","To allow clotting","To avoid skin antisepsis","To make the sample haemolysed"],"correctIndex":0,"explanation":"Bedside inoculation minimizes handling and helps maintain the recommended blood volume in culture bottles.","explanationNe":"Bedside मै blood culture bottle मा रगत राख्दा handling र contamination घट्छ तथा सही blood volume कायम गर्न सजिलो हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Blood culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Which collection method is preferred for a wound culture when deep infection is suspected?","translation":"","options":["Aspirate or tissue from the cleaned deep site","Swab of the surrounding intact skin","Swab of old dressing","Surface swab without cleaning"],"correctIndex":0,"explanation":"Aspirate or tissue from the infected deep site better represents the pathogen than a superficial swab.","explanationNe":"Deep infection मा सफा गरिएको घाउको भित्री भागबाट aspirate वा tissue लिनु सतही swab भन्दा राम्रो हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Wound specimens"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"What is the correct action before collecting a throat swab for suspected streptococcal pharyngitis?","translation":"","options":["Swab the tonsillar areas and posterior pharynx without touching tongue or cheeks","Swab the tongue only","Swab the lips","Rinse the swab in tap water"],"correctIndex":0,"explanation":"Sampling the tonsillar pillars and posterior pharynx targets the likely infection site while avoiding oral contamination.","explanationNe":"Streptococcal pharyngitis मा जिब्रो र गाला नछोई tonsillar area तथा posterior pharynx बाट swab लिनुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Throat swab"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Which specimen is appropriate for suspected pulmonary tuberculosis in an adult?","translation":"","options":["Sputum","Urine only","Conjunctival swab","Nail clipping"],"correctIndex":0,"explanation":"Sputum is commonly collected for pulmonary TB testing; the requested number and timing depend on the diagnostic protocol.","explanationNe":"फोक्सोको TB शंकामा sputum नमुना लिइन्छ; कति पटक र कुन समयमा लिने भन्ने परीक्षण प्रोटोकलमा निर्भर हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Mycobacteriology"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"What is the purpose of a sterile container for microbiology specimens?","translation":"","options":["To prevent introduction of external microorganisms","To increase specimen temperature","To preserve all organisms indefinitely","To replace correct collection technique"],"correctIndex":0,"explanation":"A sterile container reduces contamination but does not compensate for poor collection or transport.","explanationNe":"Sterile container ले बाहिरी जीवाणुको contamination घटाउँछ, तर गलत collection technique लाई सुधार्दैन।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen containers"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Which swab transport medium is commonly suitable for routine bacterial swab specimens?","translation":"","options":["Amies transport medium","Cary-Blair for every specimen","Formalin","10% neutral buffered formalin"],"correctIndex":0,"explanation":"Amies medium is commonly used to maintain viability of many bacteria on swabs during transport.","explanationNe":"धेरै routine bacterial swab का जीवाणु जीवित राखेर पठाउन Amies transport medium प्रयोग गरिन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Transport media"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"Why should microbiology specimens generally be transported promptly?","translation":"","options":["To maintain organism viability and limit overgrowth of contaminants","To sterilize the specimen","To convert bacteria into spores","To remove the need for culture"],"correctIndex":0,"explanation":"Delay can reduce recovery of fragile organisms and allow other organisms to multiply.","explanationNe":"ढिलाइ हुँदा नाजुक जीवाणु मर्न सक्छन् र अन्य जीवाणु बढी बढ्न सक्छन्; त्यसैले छिटो पठाउनुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen transport"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"Which specimen is most appropriate for diagnosing gonococcal infection in a symptomatic male with urethral discharge?","translation":"","options":["Urethral discharge swab or first-catch urine as specified by test method","Midstream urine for routine culture only","Stool","Sputum"],"correctIndex":0,"explanation":"A urethral specimen or first-catch urine may be used depending on whether culture or molecular testing is requested.","explanationNe":"लक्षण भएको पुरुषमा परीक्षणको प्रकारअनुसार urethral discharge swab वा first-catch urine प्रयोग गर्न सकिन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Genital specimens"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"What is the primary reason to avoid sending a dry swab for bacterial culture?","translation":"","options":["Organisms may lose viability during transport","It increases the swab''s sterility","It improves anaerobic growth","It prevents contamination completely"],"correctIndex":0,"explanation":"A suitable transport medium helps maintain organism viability when immediate plating is not possible.","explanationNe":"तुरुन्त culture गर्न नसक्दा उपयुक्त transport medium ले जीवाणुको viability जोगाउन मद्दत गर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Swab handling"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Which specimen is most suitable for anaerobic culture?","translation":"","options":["Deep aspirate collected and transported in an anaerobic system","Surface swab exposed to air","Saliva in an open cup","Dried skin flakes"],"correctIndex":0,"explanation":"Anaerobes may be damaged by oxygen; deep aspirates and oxygen-free transport are preferred.","explanationNe":"Anaerobic जीवाणु अक्सिजनले प्रभावित हुन सक्छन्; त्यसैले deep aspirate र oxygen-free transport प्रयोग गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Anaerobic culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"What does a Gram stain provide in the initial examination of a clinical specimen?","translation":"","options":["Rapid information about bacterial morphology and Gram reaction","Definitive antibiotic susceptibility","Viral genome sequence","Exact species identification in every case"],"correctIndex":0,"explanation":"Gram staining offers an early clue about bacterial shape, arrangement, and Gram reaction, guiding further tests.","explanationNe":"Gram stain ले जीवाणुको आकार, समूहबद्धता र Gram reaction बारे प्रारम्भिक जानकारी दिन्छ; यसले थप परीक्षण निर्देशित गर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Direct microscopy"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"Which specimen should be collected in a container with appropriate anticoagulant for blood cell counts?","translation":"","options":["Whole blood in EDTA tube","Serum in plain tube","Clotted blood","Urine in sterile cup"],"correctIndex":0,"explanation":"EDTA prevents clotting and preserves cellular components for routine haematology testing.","explanationNe":"EDTA ले रगत जम्न दिँदैन र CBC जस्ता परीक्षणका लागि रक्तकोषहरू सुरक्षित राख्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen tubes"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"What is the main reason to collect blood culture before starting antimicrobial therapy when feasible?","translation":"","options":["Prior antibiotics may reduce the chance of recovering the pathogen","Antibiotics increase blood volume","It prevents all contamination","Culture bottles contain antibiotics"],"correctIndex":0,"explanation":"Antimicrobial exposure can suppress bacterial growth and lead to false-negative cultures.","explanationNe":"Antibiotic सुरु गरेपछि जीवाणुको वृद्धि दबिन सक्छ र culture negative आउन सक्छ; सम्भव भए पहिले नमुना लिनुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Blood culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-019','BMLT','BMLT NHPC Licensing','mcq','free',19,'{"question":"Which test is commonly used for rapid detection of group A streptococcal antigen from a throat swab?","translation":"","options":["Rapid antigen detection test","Widal test","VDRL","Mantoux test"],"correctIndex":0,"explanation":"A rapid antigen detection test can provide a quick result for group A streptococcal pharyngitis.","explanationNe":"Throat swab बाट Group A Streptococcus को antigen छिटो पत्ता लगाउन rapid antigen detection test प्रयोग हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Rapid diagnostic tests"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"What is the best practice when collecting a specimen for suspected enteric fever blood culture?","translation":"","options":["Collect an adequate volume of blood using aseptic technique","Collect only a drop of blood","Use a non-sterile bottle","Add formalin to the bottle"],"correctIndex":0,"explanation":"Adequate blood volume and aseptic collection improve culture yield and reduce contamination.","explanationNe":"Enteric fever blood culture मा पर्याप्त रगत aseptic technique बाट लिनु culture yield बढाउन र contamination घटाउन महत्त्वपूर्ण हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Blood culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Which specimen is commonly used for diagnosing bacterial conjunctivitis?","translation":"","options":["Conjunctival swab from the affected eye","Nasal wash","Stool sample","Midstream urine"],"correctIndex":0,"explanation":"A swab from the affected conjunctival area can be sent for microscopy and culture when indicated.","explanationNe":"Bacterial conjunctivitis शंकामा प्रभावित आँखाको conjunctival भागबाट swab लिएर आवश्यकताअनुसार microscopy र culture गरिन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Eye specimens"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"Why is a specimen collection time recorded?","translation":"","options":["To interpret results and assess time-sensitive changes","To determine the patient''s height","To replace patient identification","To sterilize the sample"],"correctIndex":0,"explanation":"Collection time supports interpretation, transport monitoring, and correlation with treatment or clinical events.","explanationNe":"नमुना लिएको समयले नतिजा व्याख्या, transport समयको निगरानी र उपचारसँग सम्बन्ध जोड्न मद्दत गर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Documentation"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"Which sample is preferred for culture of suspected bacterial gastroenteritis?","translation":"","options":["Fresh stool specimen","Formalin-fixed stool","Dried stool on paper","Saliva"],"correctIndex":0,"explanation":"Fresh stool is preferred; appropriate transport medium is used if processing is delayed.","explanationNe":"Bacterial gastroenteritis मा ताजा दिसा उपयुक्त हुन्छ; ढिलाइ भए उपयुक्त transport medium प्रयोग गरिन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Stool culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"What is the purpose of using a negative control in a molecular diagnostic run?","translation":"","options":["To detect contamination or non-specific amplification","To prove every patient is infected","To increase target DNA concentration","To replace positive control"],"correctIndex":0,"explanation":"A negative control should remain negative; amplification suggests contamination or assay problems.","explanationNe":"Molecular test को negative control मा amplification हुनु हुँदैन; भए contamination वा assay समस्या हुन सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Molecular diagnostics"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"Which approach is correct for processing a specimen suspected to contain a highly infectious pathogen?","translation":"","options":["Follow risk assessment, appropriate containment, PPE and validated procedures","Open it on the general bench","Smell the specimen to identify it","Process without notifying staff"],"correctIndex":0,"explanation":"Risk-based biosafety precautions protect laboratory staff and the environment.","explanationNe":"अत्यधिक संक्रामक रोगजनक शंका भएको नमुना risk assessment, उपयुक्त containment, PPE र प्रमाणित प्रक्रियाअनुसार प्रशोधन गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Biosafety"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"A urine sample for culture is received in an unsterile, leaking container. What should the laboratory do?","translation":"","options":["Reject it, document the reason and request a properly collected sample","Transfer it to a sterile cup and report normally","Wipe the outside and culture it","Add disinfectant and process"],"correctIndex":0,"explanation":"A leaking, non-sterile container compromises safety and specimen integrity; rejection and recollection are appropriate.","explanationNe":"चुहिएको र non-sterile भाँडोले सुरक्षा तथा नमुनाको गुणस्तर बिगार्छ; कारण लेखेर नयाँ नमुना माग्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen rejection"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"A patient is suspected of bacterial meningitis. What is the priority after CSF reaches the laboratory?","translation":"","options":["Urgent processing and immediate communication of critical findings","Refrigerate for several days","Wait until the next routine batch","Add formalin before microscopy"],"correctIndex":0,"explanation":"CSF for suspected acute bacterial meningitis is urgent because delays can reduce organism recovery and delay treatment.","explanationNe":"Acute bacterial meningitis को CSF अत्यावश्यक हुन्छ; ढिलाइले जीवाणु पत्ता लाग्ने सम्भावना घटाउन र उपचार ढिलो गराउन सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"CSF processing"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"A sputum specimen contains mainly saliva with very few inflammatory cells on microscopy. What does this suggest?","translation":"","options":["Poor-quality specimen, likely contaminated with oral secretions","Excellent lower respiratory specimen","Confirmed tuberculosis","Confirmed viral pneumonia"],"correctIndex":0,"explanation":"Saliva-dominant sputum may not represent lower respiratory tract infection and recollection may be needed.","explanationNe":"खकारमा saliva धेरै र inflammatory cells कम हुनु नमुना मुखको secretion ले दूषित भएको संकेत हुन सक्छ; पुनः संकलन आवश्यक पर्न सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen quality"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"A wound swab is collected from an uncleaned superficial area. What is the major limitation?","translation":"","options":["It may recover colonizing flora rather than the deep pathogen","It always identifies the causative organism","It guarantees anaerobic recovery","It eliminates contamination"],"correctIndex":0,"explanation":"Superficial swabs can reflect colonizers; cleaned deep tissue or aspirate is preferable for deep infection.","explanationNe":"सतही swab मा colonizing flora आउन सक्छ; deep infection मा सफा गरिएको tissue वा aspirate राम्रो हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Wound specimens"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"A stool specimen for bacterial culture will take several hours to reach the laboratory. Which action is most appropriate?","translation":"","options":["Place it in a suitable enteric transport medium such as Cary-Blair","Add EDTA","Fix it in formalin","Leave it exposed to sunlight"],"correctIndex":0,"explanation":"Cary-Blair helps preserve enteric pathogens during transport when immediate processing is not possible.","explanationNe":"तुरुन्त परीक्षण सम्भव नभए Cary-Blair ले transport अवधिमा enteric pathogen जोगाउन मद्दत गर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Transport media"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"A blood culture bottle is underfilled. Which issue is most likely?","translation":"","options":["Reduced sensitivity because blood volume is inadequate","Increased sensitivity in all cases","Automatic identification of the organism","No effect on culture yield"],"correctIndex":0,"explanation":"Blood volume is a major determinant of blood culture sensitivity, especially in adults.","explanationNe":"Blood culture मा पर्याप्त रगत हुनु महत्त्वपूर्ण हुन्छ; कम volume हुँदा जीवाणु पत्ता लाग्ने सम्भावना घट्न सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Blood culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"A sample for anaerobic culture is collected in a routine swab and left exposed to air. What is the likely consequence?","translation":"","options":["Anaerobic organisms may be damaged and fail to grow","All aerobic organisms die","The sample becomes sterile","The specimen becomes suitable for viral culture"],"correctIndex":0,"explanation":"Oxygen exposure and unsuitable transport can reduce recovery of anaerobic bacteria.","explanationNe":"अक्सिजनको सम्पर्क र गलत transport ले anaerobic जीवाणु नष्ट वा कमजोर भई culture मा नबढ्न सक्छन्।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Anaerobic culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-008','BMLT','BMLT NHPC Licensing','mock','free',8,'{"question":"A laboratory receives two specimens with the same patient name but different identification numbers. What should staff do?","translation":"","options":["Resolve the discrepancy with the sending unit before processing","Choose either number","Change both labels to one number without confirmation","Discard both without documentation"],"correctIndex":0,"explanation":"Conflicting identifiers must be clarified to prevent patient misidentification.","explanationNe":"एउटै नाम तर फरक ID भएको अवस्थामा गलत बिरामीको नतिजा नआओस् भनेर पठाउने विभागसँग पुष्टि गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Patient identification"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-009','BMLT','BMLT NHPC Licensing','mock','free',9,'{"question":"A throat swab touches the patient''s tongue before the tonsillar area is sampled. What is the main concern?","translation":"","options":["Contamination with oral flora may affect interpretation","The swab becomes sterile","The sample is automatically positive for Streptococcus","The swab can no longer be transported"],"correctIndex":0,"explanation":"Contact with the tongue and cheeks can introduce additional oral organisms and reduce specimen quality.","explanationNe":"जिब्रो वा गाला छोएमा अन्य मुखका जीवाणु मिसिन सक्छन् र नतिजा व्याख्या गर्न कठिन हुन सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Throat swab"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-010','BMLT','BMLT NHPC Licensing','mock','free',10,'{"question":"A microbiology sample is received without the collection date and time. Why is this important?","translation":"","options":["The laboratory cannot reliably assess specimen age and transport interval","The patient''s diagnosis is already known","The sample will become positive","The container is automatically invalid for every test"],"correctIndex":0,"explanation":"Date and time help assess stability, transport delay and whether the sample meets test requirements.","explanationNe":"मिति र समयले नमुना कति पुरानो हो र transport ढिलाइ भयो कि भएन भन्ने मूल्याङ्कन गर्न मद्दत गर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Documentation"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-011','BMLT','BMLT NHPC Licensing','mock','free',11,'{"question":"A clinician requests culture from a suspected deep abscess. Which specimen should be recommended?","translation":"","options":["Aspirated pus collected aseptically","Swab from intact skin nearby","Old dressing material","A surface swab after the wound dries"],"correctIndex":0,"explanation":"Aspirated pus from the deep infected site provides a better specimen and limits surface contamination.","explanationNe":"Deep abscess बाट aseptic तरिकाले aspirate गरिएको pus राम्रो नमुना हो; यसले सतही contamination घटाउँछ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Abscess specimens"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-012','BMLT','BMLT NHPC Licensing','mock','free',12,'{"question":"A molecular assay''s negative control shows amplification. What should the technologist suspect?","translation":"","options":["Contamination or run validity failure","A true negative run","Correct calibration in every case","Absence of target in all patient samples"],"correctIndex":0,"explanation":"Unexpected amplification in a negative control suggests contamination or non-specific amplification; the run needs investigation.","explanationNe":"Negative control मा amplification देखिए contamination वा non-specific amplification शंका गर्नुपर्छ र run को validity जाँच्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Molecular diagnostics"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-013','BMLT','BMLT NHPC Licensing','mock','free',13,'{"question":"A patient has started antibiotics before blood culture collection. What should be recorded?","translation":"","options":["Antibiotic exposure and timing, and inform the clinician if relevant","Nothing; treatment history is irrelevant","Only the patient''s age","The antibiotic should be added to the culture bottle"],"correctIndex":0,"explanation":"Prior antimicrobial therapy can reduce culture yield, so the information is important for interpretation.","explanationNe":"पहिले antibiotic लिएको विवरण र समय अभिलेख गर्नुपर्छ, किनकि यसले culture yield घटाउन सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Blood culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-014','BMLT','BMLT NHPC Licensing','mock','free',14,'{"question":"A laboratory worker receives a specimen suspected of containing a high-risk pathogen. What is the first safe approach?","translation":"","options":["Use the established risk assessment and containment procedure before opening","Open it immediately to inspect the smell","Vortex it on an open bench","Ask an untrained person to handle it"],"correctIndex":0,"explanation":"Specimens with potential high-risk pathogens require appropriate containment and trained personnel before manipulation.","explanationNe":"High-risk pathogen शंका भएको नमुना खोल्नुअघि risk assessment, containment र तालिमप्राप्त कर्मचारी सुनिश्चित गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Biosafety"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-015','BMLT','BMLT NHPC Licensing','mock','free',15,'{"question":"A clinician sends a dry swab for culture after a long transport delay. What is the main concern?","translation":"","options":["Loss of viability of some organisms","Excessive preservation of all bacteria","Guaranteed pure growth","Increased specimen volume"],"correctIndex":0,"explanation":"Without suitable transport conditions, some organisms may not survive long delays.","explanationNe":"उपयुक्त transport medium र अवस्था नभए लामो ढिलाइमा केही जीवाणु जीवित नरहन सक्छन्।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Swab transport"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-016','BMLT','BMLT NHPC Licensing','mock','free',16,'{"question":"A CSF specimen for bacterial culture is mistakenly placed in a refrigerator. Why may this be problematic?","translation":"","options":["Some fastidious pathogens may lose viability at low temperature","Refrigeration sterilizes every pathogen","It increases bacterial growth uniformly","It converts bacteria to viruses"],"correctIndex":0,"explanation":"For suspected acute bacterial meningitis, CSF should be processed urgently; refrigeration can impair recovery of certain fragile organisms.","explanationNe":"Acute bacterial meningitis को CSF तुरुन्त प्रशोधन गर्नुपर्छ; चिस्याउँदा केही नाजुक जीवाणु नबढ्न सक्छन्।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"CSF transport"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-017','BMLT','BMLT NHPC Licensing','mock','free',17,'{"question":"A sample for culture is collected after antiseptic has contaminated the specimen container. What is the risk?","translation":"","options":["Antiseptic may inhibit microbial growth and cause false-negative culture","It guarantees better growth","It increases bacterial count","It has no possible effect"],"correctIndex":0,"explanation":"Antiseptic carryover can inhibit organisms in the specimen and reduce culture recovery.","explanationNe":"नमुना भाँडोमा antiseptic मिसिए जीवाणुको वृद्धि रोकिन सक्छ र culture false-negative आउन सक्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen contamination"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-018','BMLT','BMLT NHPC Licensing','mock','free',18,'{"question":"A laboratory is asked to culture a specimen collected in formalin. What is the correct response?","translation":"","options":["Explain that formalin-fixed specimens are unsuitable for routine culture and request a fresh specimen","Culture it after boiling","Dilute formalin with saline and proceed","Use it for blood culture"],"correctIndex":0,"explanation":"Formalin kills or damages microorganisms and is used for tissue fixation, not routine viable culture.","explanationNe":"Formalin ले सूक्ष्मजीव मार्न वा क्षति पुर्‍याउन सक्छ; यो tissue fixation का लागि हो, जीवित culture का लागि होइन।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen suitability"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-019','BMLT','BMLT NHPC Licensing','mock','free',19,'{"question":"A throat swab for culture is transported in an appropriate medium but reaches the laboratory after a short delay. What should staff do?","translation":"","options":["Process according to the medium and test-specific stability requirements","Reject every delayed specimen automatically","Freeze it immediately","Add formalin"],"correctIndex":0,"explanation":"Acceptability depends on the organism, medium, time and validated laboratory protocol.","explanationNe":"नमुना स्वीकार गर्ने निर्णय organism, transport medium, समय र प्रयोगशालाको validated protocol अनुसार गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen transport"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-020','BMLT','BMLT NHPC Licensing','mock','free',20,'{"question":"A urine culture reports mixed growth of several organisms from a poorly collected sample. What is the likely interpretation?","translation":"","options":["Possible contamination; correlate clinically and consider recollection","Definite polymicrobial UTI in every patient","Proof of tuberculosis","Proof of viral infection"],"correctIndex":0,"explanation":"Mixed growth in a poor-quality clean-catch specimen often indicates contamination, though clinical context matters.","explanationNe":"खराब तरिकाले संकलित urine मा धेरै प्रकारका जीवाणु देखिनु contamination हुन सक्छ; लक्षणसँग मिलाएर आवश्यक परे पुनः नमुना लिनुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Urine culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-021','BMLT','BMLT NHPC Licensing','mock','free',21,'{"question":"A sample for gonorrhoea NAAT is collected as first-catch urine. Which instruction is important?","translation":"","options":["Follow assay-specific collection instructions and avoid substituting midstream urine","Always collect 24-hour urine","Add anticoagulant","Collect only after formalin fixation"],"correctIndex":0,"explanation":"First-catch urine is used for many urogenital NAAT protocols; exact instructions depend on the assay.","explanationNe":"धेरै urogenital NAAT मा first-catch urine प्रयोग हुन्छ; सही तरिका सम्बन्धित kit/protocol अनुसार पालना गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Molecular diagnostics"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-022','BMLT','BMLT NHPC Licensing','mock','free',22,'{"question":"A microbiology specimen arrives in a container with no leak-proof secondary packaging. What is the key concern?","translation":"","options":["Risk of exposure during transport and handling","Improved organism identification","Automatic specimen sterilization","Increased test specificity"],"correctIndex":0,"explanation":"Leak-proof secondary containment protects staff, couriers and the environment from infectious material.","explanationNe":"Leak-proof secondary packaging ले transport र handling गर्दा कर्मचारी तथा वातावरणलाई संक्रमणको जोखिमबाट जोगाउँछ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Biosafety"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-023','BMLT','BMLT NHPC Licensing','mock','free',23,'{"question":"A laboratory wants to reduce contamination in blood cultures. Which measure is most important?","translation":"","options":["Proper skin antisepsis and aseptic collection technique","Touching the cleaned site repeatedly","Using expired culture bottles","Collecting through a non-sterile container"],"correctIndex":0,"explanation":"Correct skin antisepsis and aseptic technique are central to reducing blood culture contamination.","explanationNe":"Blood culture contamination घटाउन छालाको सही antisepsis र aseptic collection अत्यन्त महत्त्वपूर्ण हुन्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Blood culture"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-024','BMLT','BMLT NHPC Licensing','mock','free',24,'{"question":"A specimen is received in the correct container but has exceeded the validated stability period. What should the laboratory do?","translation":"","options":["Assess against the test-specific rejection policy and consult the responsible clinician","Ignore the delay","Change the collection time","Report results without qualification"],"correctIndex":0,"explanation":"Specimen stability is test-specific; the laboratory should follow validated acceptance criteria and document decisions.","explanationNe":"नमुनाको stability परीक्षणअनुसार फरक हुन्छ; validated acceptance criteria पालना गरी आवश्यक परे चिकित्सकसँग समन्वय गर्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Specimen stability"}'::jsonb,true),
('bmlt-clinmicrodiagnostic1-mock-025','BMLT','BMLT NHPC Licensing','mock','free',25,'{"question":"A Gram-stained smear from sputum shows many squamous epithelial cells and few neutrophils. What is the best next step?","translation":"","options":["Request a better-quality sputum specimen if clinically appropriate","Report it as confirmed bacterial pneumonia","Perform susceptibility testing on the smear","Label it as a sterile specimen"],"correctIndex":0,"explanation":"Many squamous epithelial cells suggest oral contamination; a better lower respiratory specimen may be needed.","explanationNe":"Squamous epithelial cells धेरै र neutrophils कम हुनु मुखको contamination को संकेत हो; आवश्यक भए राम्रो खकार पुनः माग्नुपर्छ।","topic":"Clinical Microbiology – Diagnostic Methods & Specimen Processing","subtopic":"Direct microscopy"}'::jsonb,true)
